const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await ee.data.authenticateViaPrivateKey(privateKey);
  await ee.initialize();

  // 1. Geometry & Time Definitions
  const mekele = ee.Geometry.Point(39.479, 13.496).buffer(20000); // Mekele, Ethiopia, with a 20km buffer

  const startYear1 = '1984-01-01';
  const endYear1 = '1986-12-31'; // Around 1984

  const startYear2 = '2022-01-01'; // Using recent data for "around 2025"
  const endYear2 = '2024-12-31';

  const urbanThreshold = 0.05; // NDBI threshold for urban areas. This is an empirically chosen value.

  // Function to mask clouds for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('pixel_qa');
    const cloud = qa.bitwiseAnd(1 << 5)
      .and(qa.bitwiseAnd(1 << 7))
      .or(qa.bitwiseAnd(1 << 3)); // Clouds and cloud shadow and saturated
    const mask = image.select('qa_radsat').eq(0).and(cloud.not());
    return image.updateMask(mask).divide(10000); // Apply scaling and mask
  }

  // Function to mask clouds for Landsat 8/9
  function maskL89Clouds(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitmask = (1 << 3);
    const cloudsBitmask = (1 << 5);

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitmask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitmask).eq(0));

    return image.updateMask(mask).select("B[0-9]*").divide(10000); // Apply scaling and mask
  }

  // Function to calculate NDBI for Landsat 5
  function addNDBI_L5(image) {
    return image.addBands(image.normalizedDifference(['B5', 'B4']).rename('NDBI'));
  }

  // Function to calculate NDBI for Landsat 8/9
  function addNDBI_L89(image) {
    return image.addBands(image.normalizedDifference(['B6', 'B5']).rename('NDBI'));
  }

  // 2. Data Acquisition & Check for Period 1 (1984)
  let collection1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(mekele)
    .filterDate(startYear1, endYear1)
    .map(maskL5Clouds)
    .map(addNDBI_L5);

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log("No Landsat 5 images found for 1984-1986.");
    // Try expanding search or fallback, but for this specific question, it's a hard dependency.
    console.log("C1");
    return;
  }
  const image1 = collection1.median();
  const countPixels1 = await image1.select('NDBI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mekele,
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  if (countPixels1 === 0) {
    console.log(`1984-1986 Images: ${size1}. No valid pixels after cloud masking for 1984.`);
    console.log("C2");
    return;
  }
  console.log(`1984-1986 Images: ${size1} (Valid Pixels: ${countPixels1})`);

  // 3. Data Acquisition & Check for Period 2 (2025/latest)
  let collection2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(mekele)
    .filterDate(startYear2, endYear2)
    .map(maskL89Clouds)
    .map(addNDBI_L89);

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No Landsat 8 images found for ${startYear2}-${endYear2}.`);
    // Fallback to Landsat 9
    collection2 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(mekele)
      .filterDate(startYear2, endYear2)
      .map(maskL89Clouds)
      .map(addNDBI_L89);
    const size2_L9 = await collection2.size().getInfo();
    if (size2_L9 === 0) {
      console.log(`No Landsat 9 images found for ${startYear2}-${endYear2} either.`);
      console.log("C1");
      return;
    }
    console.log(`Using Landsat 9. Images: ${size2_L9}`);
  }
  const image2 = collection2.median();
  const countPixels2 = await image2.select('NDBI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mekele,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  if (countPixels2 === 0) {
    console.log(`${startYear2}-${endYear2} Images: ${size2}. No valid pixels after cloud masking for ${startYear2}-${endYear2}.`);
    console.log("C2");
    return;
  }
  console.log(`${startYear2}-${endYear2} Images: ${size2} (Valid Pixels: ${countPixels2})`);

  // 4. Urban Area Calculation
  const urban1 = image1.select('NDBI').gt(urbanThreshold).rename('urban_area');
  const urban2 = image2.select('NDBI').gt(urbanThreshold).rename('urban_area');

  // Calculate area in square kilometers
  const areaImage1 = urban1.multiply(ee.Image.pixelArea()).divide(1e6); // Convert to km^2
  const areaImage2 = urban2.multiply(ee.Image.pixelArea()).divide(1e6);

  const urbanArea1_km2 = await areaImage1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mekele,
    scale: 30,
    maxPixels: 1e9
  }).get('urban_area').getInfo();

  const urbanArea2_km2 = await areaImage2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mekele,
    scale: 30,
    maxPixels: 1e9
  }).get('urban_area').getInfo();

  if (urbanArea1_km2 === null || urbanArea2_km2 === null || isNaN(urbanArea1_km2) || isNaN(urbanArea2_km2)) {
    console.log("Calculation of urban area failed (NaN/Null).");
    console.log("C3");
    return;
  }

  console.log(`Urban area in 1984 (approx.): ${urbanArea1_km2.toFixed(2)} km^2`);
  console.log(`Urban area in 2022-2024 (approx.): ${urbanArea2_km2.toFixed(2)} km^2`);

  // 5. Validation & Final Answer
  if (urbanArea2_km2 > urbanArea1_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

runAnalysis().catch(e => {
  console.error("Analysis failed: ", e);
  console.log("D"); // Indicate a general error or syntax issue
});
